/**
 * R-1849 — posted year-end profit splits (partner_appropriations + lines) and the two RPCs that
 * write them (migration 20261025030249_r1849_partner_appropriation.sql). Posting and undoing
 * are one database call each; the function re-checks every figure against the law.
 *
 * Untyped client: the tables are newer than database.types.ts (regenerated by the manager).
 */
"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { SupabaseClient } from "@supabase/supabase-js";
import { toast } from "sonner";

import { createClient } from "@/lib/supabase/client";
import { useCurrentUser } from "@/lib/hooks/useCurrentUser";
import { toastError } from "@/lib/errors/toast-error";
import { fyLabelOfYear } from "@/lib/dates/ist";
import type { PostedSplit } from "@/lib/accounting/partner-capital";
import type { Appropriation } from "@/lib/accounting/partner-appropriation";

const untyped = () => createClient() as unknown as SupabaseClient;

export const PARTNER_APPROPRIATIONS_KEY = ["partner_appropriations"] as const;

/** Code deployed before the migration: nothing posted yet — every other failed read is an error. */
export function isAppropriationTableMissing(err: unknown): boolean {
  const m = err instanceof Error ? err.message : String(err ?? "");
  return /partner_appropriation/.test(m) && /(does not exist|could not find|schema cache)/i.test(m);
}

export interface PostedSplitDetail extends PostedSplit {
  id: string;
  interestTotal: number;
  bookProfit: number;
  maxRemuneration: number;
  remunerationTotal: number;
  residual: number;
  tdsTotal: number;
  createdAt: string;
  lines: (PostedSplit["lines"][number] & {
    sharePct: number; capitalBase: number; interestDays: number; deedInterestPct: number; interestPct: number;
    working: boolean; deedRemuneration: number;
  })[];
}

type HeaderRow = {
  id: string; fy_start: number; posted_on: string; net_profit: number; interest_total: number; book_profit: number;
  max_remuneration: number; remuneration_total: number; residual: number; tds_total: number; created_at: string;
  partner_appropriation_lines: {
    partner_id: string; share_pct: number; capital_base: number; interest_days: number; deed_interest_pct: number;
    interest_pct: number; interest: number; working: boolean; deed_remuneration: number; remuneration: number;
    profit_share: number; tds: number; tds_section: string | null;
  }[];
};

/** Pure: the database rows → the shape the screens use (numbers, not strings). */
export function toPostedSplits(rows: readonly HeaderRow[]): PostedSplitDetail[] {
  const n = (v: unknown) => Number(v) || 0;
  return rows.map((h) => ({
    id: h.id, fyStart: n(h.fy_start), postedOn: h.posted_on, netProfit: n(h.net_profit),
    interestTotal: n(h.interest_total), bookProfit: n(h.book_profit), maxRemuneration: n(h.max_remuneration),
    remunerationTotal: n(h.remuneration_total), residual: n(h.residual), tdsTotal: n(h.tds_total), createdAt: h.created_at,
    lines: (h.partner_appropriation_lines ?? []).map((l) => ({
      partnerId: l.partner_id, interest: n(l.interest), remuneration: n(l.remuneration), profitShare: n(l.profit_share),
      tds: n(l.tds), tdsSection: l.tds_section, sharePct: n(l.share_pct), capitalBase: n(l.capital_base),
      interestDays: n(l.interest_days), deedInterestPct: n(l.deed_interest_pct), interestPct: n(l.interest_pct),
      working: Boolean(l.working), deedRemuneration: n(l.deed_remuneration),
    })),
  })).sort((a, b) => a.fyStart - b.fyStart);
}

export function usePartnerAppropriations(enabled = true) {
  const me = useCurrentUser();
  const tenantId = me.data?.tenantId ?? null;
  return useQuery({
    queryKey: [...PARTNER_APPROPRIATIONS_KEY, tenantId],
    enabled: enabled && Boolean(tenantId),
    queryFn: async (): Promise<PostedSplitDetail[]> => {
      const { data, error } = await untyped()
        .from("partner_appropriations")
        .select("id, fy_start, posted_on, net_profit, interest_total, book_profit, max_remuneration, remuneration_total, residual, tds_total, created_at, partner_appropriation_lines(partner_id, share_pct, capital_base, interest_days, deed_interest_pct, interest_pct, interest, working, deed_remuneration, remuneration, profit_share, tds, tds_section)")
        .order("fy_start", { ascending: true });
      if (error) {
        if (isAppropriationTableMissing(error.message)) return [];
        throw new Error(error.message);
      }
      return toPostedSplits((data ?? []) as HeaderRow[]);
    },
  });
}

/** Pure: what post_partner_appropriation is sent. */
export function postPayload(a: Appropriation): { p_fy_start: number; p_net_profit: number; p_lines: Record<string, unknown>[] } {
  return {
    p_fy_start: a.fyStart,
    p_net_profit: a.netProfit,
    p_lines: a.lines.map((l) => ({
      partner_id: l.partnerId, capital_base: l.capitalBase, interest_days: l.interestDays,
      deed_interest_pct: l.deedInterestPct, interest_pct: l.interestPct, interest: l.interest, working: l.working,
      deed_remuneration: l.working ? l.deedRemuneration : 0, remuneration: l.remuneration,
      profit_share: l.profitShare, tds: l.tds,
    })),
  };
}

function invalidateAll(qc: ReturnType<typeof useQueryClient>) {
  qc.invalidateQueries({ queryKey: PARTNER_APPROPRIATIONS_KEY });
  qc.invalidateQueries({ queryKey: ["balance-sheet"] });
  qc.invalidateQueries({ queryKey: ["statutory-dues"] });
}

export function usePostPartnerAppropriation() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (a: Appropriation) => {
      const { data, error } = await untyped().rpc("post_partner_appropriation", postPayload(a));
      if (error) throw new Error(error.message);
      return data as string;
    },
    onSuccess: (_d, a) => {
      invalidateAll(qc);
      toast.success(`Profit for FY ${fyLabelOfYear(a.fyStart)} split among the partners`);
    },
    onError: (err) => toastError(err, { fallback: "Couldn't post the profit split" }),
  });
}

export function useUndoPartnerAppropriation() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (fyStart: number) => {
      const { error } = await untyped().rpc("undo_partner_appropriation", { p_fy_start: fyStart });
      if (error) throw new Error(error.message);
    },
    onSuccess: (_d, fyStart) => {
      invalidateAll(qc);
      toast.success(`Profit split for FY ${fyLabelOfYear(fyStart)} undone`);
    },
    onError: (err) => toastError(err, { fallback: "Couldn't undo the profit split" }),
  });
}
